CREATE OR REPLACE FUNCTION e34_private.affiliate_workspace(section_name text DEFAULT 'overview'::text, search_text text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare names text[];t text;rows jsonb;output jsonb='{}';begin
 if not e34_private.commercial_admin() then raise exception 'Administrator permission and MFA required';end if;
 if char_length(search_text)>120 then raise exception 'Search is too long';end if;
 names=case section_name when 'applications' then array['affiliate_programs','affiliate_applications'] when 'retailers' then array['affiliate_networks','affiliate_programs','affiliate_merchants','affiliate_credentials_metadata'] when 'matching' then array['merchant_products','merchant_product_identifiers','affiliate_match_reviews','affiliate_links','merchant_offers','affiliate_import_jobs'] when 'advertising' then array['commercial_settings','advertising_placements','advertising_campaigns','sponsorships'] when 'revenue' then array['affiliate_commissions','sponsorship_payments','revenue_records'] else array[]::text[] end;
 foreach t in array names loop
  execute format('select coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) from(select * from e34_private.%I where $1='''' or to_jsonb(%I)::text ilike ''%%''||$1||''%%'' order by updated_at desc,id limit 100)x',t,t) into rows using search_text;
  output=output||jsonb_build_object(t,rows);
 end loop;
 return output||jsonb_build_object('counts',jsonb_build_object('approved_programs',(select count(*) from e34_private.affiliate_programs where status='approved'),'pending_applications',(select count(*) from e34_private.affiliate_applications where status in ('submitted','under_review','awaiting_owner_submission')),'active_retailers',(select count(*) from e34_private.affiliate_merchants where active),'published_offers',(select count(*) from e34_private.merchant_offers where published),'unreviewed_matches',(select count(*) from e34_private.affiliate_match_reviews where review_status='pending'),'unmatched_oem_numbers',(select count(*) from public.parts p where number_normalized is not null and not exists(select 1 from e34_private.affiliate_match_reviews r where r.part_id=p.id and r.review_status='approved')),'referral_clicks',(select coalesce(sum(clicks),0) from e34_private.affiliate_clicks_daily where day>=current_date-29),'campaign_impressions',(select coalesce(sum(impressions),0) from e34_private.advertising_daily where day>=current_date-29)),
 'monthly_revenue',coalesce((select jsonb_agg(to_jsonb(x)) from(select date_trunc('month',occurred_on)::date as month,currency,channel,sum(case when kind='estimate' then amount_cents else 0 end)::text as estimated_cents,sum(case when kind='earning' then amount_cents when kind='reversal' then -amount_cents else 0 end)::text as confirmed_net_cents,sum(case when kind='receipt' then amount_cents else 0 end)::text as received_cents from e34_private.revenue_records group by 1,2,3 order by 1 desc,2,3 limit 180)x),'[]'::jsonb),
 'programs',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'status',status,'tracking_hosts',tracking_hosts,'query_parameters',query_parameters,'link_template',link_template,'public_parameters',public_parameters)),'[]'::jsonb) from e34_private.affiliate_programs),
 'referrals_by_merchant',coalesce((select jsonb_agg(to_jsonb(x)) from(select m.id,m.name,sum(c.clicks)::text as clicks from e34_private.affiliate_clicks_daily c join e34_private.affiliate_links l on l.id=c.link_id join e34_private.affiliate_merchants m on m.id=l.merchant_id where c.day>=current_date-29 group by m.id,m.name order by sum(c.clicks) desc,m.id limit 20)x),'[]'::jsonb),
 'popular_linked_parts',coalesce((select jsonb_agg(to_jsonb(x)) from(select p.id,p.name,p.number_normalized,sum(c.clicks)::text as clicks from (select distinct r.part_id,l.id as link_id from e34_private.affiliate_match_reviews r join e34_private.affiliate_links l on l.product_id=r.product_id) identities join public.parts p on p.id=identities.part_id join e34_private.affiliate_clicks_daily c on c.link_id=identities.link_id where c.day>=current_date-29 group by p.id,p.name,p.number_normalized order by sum(c.clicks) desc,p.id limit 20)x),'[]'::jsonb),
 'campaign_activity',coalesce((select jsonb_agg(to_jsonb(x)) from(select c.id,c.title as name,c.status,c.starts_at,c.ends_at,coalesce(sum(d.impressions),0)::text as impressions,coalesce(sum(d.clicks),0)::text as clicks from e34_private.advertising_campaigns c left join e34_private.advertising_daily d on d.campaign_id=c.id and d.day>=current_date-29 group by c.id,c.title,c.status,c.starts_at,c.ends_at order by c.updated_at desc,c.id limit 100)x),'[]'::jsonb),
 'advertising_enabled',(select advertising_enabled from e34_private.commercial_settings where id='site'),
 'merchants',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'program_id',program_id,'allowed_hosts',allowed_hosts)),'[]'::jsonb) from e34_private.affiliate_merchants));
end$function$

CREATE OR REPLACE FUNCTION e34_private.appeal_community_restriction(restriction uuid, explanation text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare new_id uuid; v_actor uuid:=auth.uid();
begin
 if v_actor is null or not exists(select 1 from e34_private.community_restrictions where id=restriction and user_id=v_actor) then raise exception 'Restriction unavailable'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_actor::text,0));
 if exists(select 1 from public.community_appeals where restriction_id=restriction and user_id=v_actor and status<>'resolved') then raise exception 'An appeal is already open'; end if;
 if (select count(*) from public.community_appeals where user_id=v_actor and created_at>now()-interval '1 day')>=3 then raise exception 'Appeal limit reached'; end if;
 insert into public.community_appeals(user_id,restriction_id,body) values(v_actor,restriction,explanation) returning id into new_id; return new_id;
end $function$

CREATE OR REPLACE FUNCTION e34_private.capture_catalog_position()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='INSERT' or new.record_sha256 is distinct from old.record_sha256 then
  insert into e34_private.catalog_position_history(position_id,source_sha256,snapshot) values(new.id,new.source_sha256,to_jsonb(new));
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION e34_private.check_twin_job_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.user_id<>old.user_id then raise exception 'Submission ownership is immutable'; end if;
 if new.status not in ('needs-evidence','failed') and not exists(select 1 from public.reconstruction_evidence where job_id=new.id) then raise exception 'Source evidence is required before processing'; end if;
 if new.status='published' and not exists(select 1 from public.geometry_revisions g join public.three_d_assets a on a.id=g.asset_id where g.id=new.published_geometry_revision_id and a.publication_status='published') then raise exception 'A reviewed published geometry revision is required'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION e34_private.claim_username(chosen_username text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid := auth.uid(); existing text;
begin
 if uid is null or not exists(select 1 from auth.users where id=uid and email_confirmed_at is not null) then raise exception 'A verified account is required'; end if;
 if chosen_username is null or chosen_username !~ '^[a-z][a-z0-9_]{2,23}$' then raise exception 'Use 3–24 lowercase letters, numbers or underscores, starting with a letter'; end if;
 if chosen_username in ('admin','administrator','moderator','owner','support','staff','e34lore','e34_lore') then raise exception 'That username is reserved'; end if;
 -- Per-account lock handles simultaneous first claims; UNIQUE handles collisions.
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 select username into existing from public.profiles where id=uid for update;
 if existing is not null and existing<>chosen_username then raise exception 'Your username is already set'; end if;
 insert into public.profiles(id,username,display_name) values(uid,chosen_username,chosen_username)
 on conflict(id) do update set username=excluded.username,display_name=excluded.display_name;
 return chosen_username;
exception when unique_violation then raise exception 'That username is already taken';
end $function$

CREATE OR REPLACE FUNCTION e34_private.community_can_contribute(actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if actor is null then raise exception 'Sign in to contribute'; end if;
 if not exists(select 1 from auth.users where id=actor and email_confirmed_at is not null) and not (
   coalesce(current_setting('e34.guest_submission',true)=actor::text,false) and
   exists(select 1 from auth.users where id=actor and is_anonymous is true)
 ) then raise exception 'Confirm your email before contributing'; end if;
 if exists(select 1 from e34_private.community_restrictions where user_id=community_can_contribute.actor and kind<>'warning' and revoked_at is null and (expires_at is null or expires_at>now())) then raise exception 'Posting is restricted. See Community settings for the reason and appeal option.'; end if;
end $function$

CREATE OR REPLACE FUNCTION e34_private.feature_garage(entry uuid, featured boolean, reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if not e34_private.has_role('moderator') or coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception 'Moderator permission and MFA required'; end if;
 if char_length(btrim(reason)) not between 10 and 2000 then raise exception 'Record a feature reason in 10–2000 characters'; end if;
 if featured and not exists(select 1 from public.garage_photos where garage_id=entry and state='approved') then raise exception 'Approve a car photo before featuring this car'; end if;
 update public.garage_showcases set featured_at=case when featured then now() else null end where id=entry and (not featured or (published and not hidden));
 if not found then raise exception 'Published car unavailable'; end if;
 insert into e34_private.audit_events(actor_id,action,table_name,record_id,metadata) values(auth.uid(),case when featured then 'garage:feature' else 'garage:unfeature' end,'garage_showcases',entry::text,jsonb_build_object('reason',reason));
end$function$

CREATE OR REPLACE FUNCTION e34_private.gate_twin_accuracy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare accuracy_axis text; accuracy_decision text;
begin
 foreach accuracy_axis in array array['visual','dimensions','alignment','mechanical','removal'] loop
  accuracy_decision=new.accuracy->>accuracy_axis;
  if accuracy_decision is null or accuracy_decision not in ('missing','illustrative','source-checked','verified','disputed') then raise exception 'Five independent accuracy states are required'; end if;
  if accuracy_decision='verified' and not exists(select 1 from public.accuracy_reviews r where r.geometry_revision_id=new.id and r.axis=accuracy_axis and r.decision='verified' and r.reviewer_id is not null and r.discrepancies='') then raise exception 'Verified geometry requires a recorded reviewer, method and evidence'; end if;
 end loop;
 if new.accuracy->>'dimensions'='verified' and (new.meters_per_unit is null or not exists(select 1 from public.geometry_measurements m where m.geometry_revision_id=new.id and m.review_state='verified' and m.independent_check and m.tolerance is not null and m.reviewer_id is not null)) then raise exception 'Verified dimensions require independent measurements and tolerances'; end if;
 if new.runtime_path is not null and (new.runtime_path like '%..%' or new.runtime_path like '%//%') then raise exception 'Invalid runtime asset path'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION e34_private.guard_commercial_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p e34_private.affiliate_programs; m e34_private.affiliate_merchants; product e34_private.merchant_products; match e34_private.affiliate_match_reviews; link e34_private.affiliate_links; s e34_private.sponsorships; original e34_private.revenue_records; h text;v record;
begin
 new.updated_at=clock_timestamp();
 for v in select key,value from jsonb_each_text(to_jsonb(new)) where key in ('website_url','application_url','official_source_url','approval_evidence_url','product_url','source_url','image_url','image_permission_url','rule_source_url','destination_url','tracking_url','contract_evidence_url','creative_permission_url','evidence_url','logo_url') and value is not null loop
  if e34_private.commercial_url_host(v.value) is null then raise exception 'Use credential-free public HTTPS URLs for commercial evidence and destinations';end if;
 end loop;
 if tg_table_name='affiliate_programs' then
  if new.status='approved' and (new.approved_at is null or new.terms_checked_at is null or e34_private.commercial_url_host(new.approval_evidence_url) is null) then raise exception 'Approved programs need dated approval and terms evidence';end if;
  foreach h in array new.tracking_hosts loop if h !~ '^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$' then raise exception 'Use exact authorized tracking hostnames';end if;end loop;
  if exists(select 1 from jsonb_each_text(new.public_parameters) x where x.key not in ('publisher_id','campaign_id','program_id') or char_length(x.value)>200 or x.value !~ '^[A-Za-z0-9_.:-]+$') then raise exception 'Only documented public tracking identifiers belong here';end if;
 elsif tg_table_name='affiliate_merchants' then
  select * into p from e34_private.affiliate_programs where id=new.program_id;
  foreach h in array new.allowed_hosts loop if h !~ '^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$' then raise exception 'Use exact retailer hostnames';end if;end loop;
  if new.active and (p.status<>'approved' or p.expires_at<=now()) then raise exception 'Approve the program before activating a retailer';end if;
 elsif tg_table_name='merchant_products' then
  if tg_op='UPDATE' and (new.merchant_id,new.retailer_sku) is distinct from (old.merchant_id,old.retailer_sku) then raise exception 'Create a new product rather than moving its retailer identity';end if;
  select * into m from e34_private.affiliate_merchants where id=new.merchant_id;
  if not coalesce(e34_private.commercial_url_host(new.product_url)=any(m.allowed_hosts),false) then raise exception 'Product URL must use an authorized retailer host';end if;
  if e34_private.commercial_url_host(new.source_url) is null then raise exception 'A public HTTPS source is required';end if;
  if new.image_authorized and (e34_private.commercial_url_host(new.image_url) is null or e34_private.commercial_url_host(new.image_permission_url) is null) then raise exception 'Product images need permission evidence';end if;
 elsif tg_table_name='merchant_product_identifiers' then
  if tg_op='UPDATE' and new.product_id<>old.product_id then raise exception 'Product identifiers cannot move between products';end if;
  if e34_private.commercial_url_host(new.source_url) is null then raise exception 'Identifier evidence requires HTTPS';end if;
 elsif tg_table_name='affiliate_match_reviews' then
  if e34_private.commercial_url_host(new.source_url) is null then raise exception 'Match evidence requires HTTPS';end if;
  if new.scope_position_id is not null and not exists(select 1 from public.part_assembly_positions where id=new.scope_position_id and part_id=new.part_id and active) then raise exception 'Choose an active source position for this exact part';end if;
  if new.review_status='approved' then
   if new.kind in ('unverified_candidate','known_incompatible') then raise exception 'An unverified or incompatible candidate cannot be approved';end if;
   if new.kind='exact_verified' and new.basis<>'oem_identity' then raise exception 'Exact matching requires OEM identifier evidence';end if;
   if new.basis='oem_identity' and (new.part_id<>new.matched_part_id or not exists(select 1 from e34_private.merchant_product_identifiers i join public.parts b on b.number_normalized=i.value where i.product_id=new.product_id and i.scheme='bmw_oem' and b.id=new.part_id)) then raise exception 'Exact matching needs the canonical BMW identifier';end if;
   if new.basis='direct_supersession' and not exists(select 1 from public.part_supersessions where id=new.direct_supersession_id and previous_part_id=new.part_id and replacement_part_id=new.matched_part_id and position_id=new.scope_position_id) then raise exception 'Replacement matching needs a direct source-scoped supersession';end if;
   if new.basis='direct_supersession' and new.kind<>'conditional' and exists(select 1 from public.part_supersessions where id=new.direct_supersession_id and conditions<>'[]'::jsonb) then raise exception 'Source-conditional supersessions must remain conditional';end if;
   if new.basis='direct_supersession' and not exists(select 1 from e34_private.merchant_product_identifiers i join public.parts b on b.number_normalized=i.value where i.product_id=new.product_id and i.scheme='bmw_oem' and b.id=new.matched_part_id) then raise exception 'The retailer identifier must match the direct replacement target';end if;
   if new.basis='documented_equivalent' and char_length(trim(new.compatibility_notes))<40 then raise exception 'An aftermarket equivalent needs specific documented evidence';end if;
   new.reviewed_by=auth.uid();new.reviewed_at=clock_timestamp();
  else new.reviewed_by=null;new.reviewed_at=null;end if;
 elsif tg_table_name='affiliate_import_jobs' then
  if new.sync_enabled then raise exception 'Scheduled sync needs an authorized feed connector; use a reviewed file import until it is configured';end if;
 elsif tg_table_name='affiliate_links' then
  select * into m from e34_private.affiliate_merchants where id=new.merchant_id;select * into p from e34_private.affiliate_programs where id=m.program_id;
  if not coalesce(e34_private.commercial_url_host(new.destination_url)=any(m.allowed_hosts),false) or not coalesce(e34_private.commercial_url_host(new.tracking_url)=any(p.tracking_hosts),false) or e34_private.commercial_url_host(new.rule_source_url) is null then raise exception 'The link destination or tracking host is not authorized';end if;
  if new.product_id is not null and not exists(select 1 from e34_private.merchant_products where id=new.product_id and merchant_id=new.merchant_id and product_url=new.destination_url) then raise exception 'Link must use this retailer product destination';end if;
  if exists(select 1 from regexp_split_to_table(split_part(new.tracking_url,'?',2),'&') q where q<>'' and not (split_part(q,'=',1)=any(p.query_parameters))) then raise exception 'Tracking query contains an unapproved parameter';end if;
  if new.active and (not m.active or p.status<>'approved' or p.expires_at<=now() or new.expires_at<=now() or new.check_status<>'ok' or new.last_checked_at is null or new.last_checked_at<now()-interval '30 days') then raise exception 'Link activation requires an approved current program and a recently checked link';end if;
 elsif tg_table_name='merchant_offers' then
  select * into match from e34_private.affiliate_match_reviews where id=new.match_id;select * into link from e34_private.affiliate_links where id=new.link_id;
  if link.product_id is distinct from match.product_id then raise exception 'Offer must use the matched product link';end if;
  if new.published and (match.review_status<>'approved' or match.kind in ('unverified_candidate','known_incompatible') or not link.active) then raise exception 'Only approved reviewed matches and active links may be published';end if;
  if new.price_authorized and (new.price_cents is null or new.price_observed_at is null or new.price_valid_until is null or new.price_valid_until<=new.price_observed_at) then raise exception 'A price needs an authorized dated observation and expiry';end if;
  if new.availability_authorized and (new.availability is null or new.availability_observed_at is null or new.availability_valid_until is null or new.availability_valid_until<=new.availability_observed_at) then raise exception 'Availability needs an authorized dated observation and expiry';end if;
  if new.shipping_authorized and (trim(new.shipping_information)='' or new.shipping_observed_at is null or new.shipping_valid_until is null or new.shipping_valid_until<=new.shipping_observed_at) then raise exception 'Shipping information needs an authorized dated observation and expiry';end if;
 elsif tg_table_name='sponsorships' then
  if e34_private.commercial_url_host(new.website_url) is null then raise exception 'Sponsor website must use HTTPS';end if;
  if new.status='approved' and (e34_private.commercial_url_host(new.contract_evidence_url) is null or new.contract_cents is null) then raise exception 'Sponsor approval requires recorded contract evidence';end if;
 elsif tg_table_name='advertising_campaigns' then
  select * into s from e34_private.sponsorships where id=new.sponsorship_id;
  if e34_private.commercial_url_host(new.destination_url) is distinct from e34_private.commercial_url_host(s.website_url) or e34_private.commercial_url_host(new.destination_url) is null then raise exception 'Campaign link must use the sponsor website';end if;
  if e34_private.commercial_url_host(new.creative_permission_url) is null then raise exception 'Record creative permission';end if;
  if new.image_url is not null and (e34_private.commercial_url_host(new.image_url) is null or char_length(trim(new.image_alt))<5) then raise exception 'Creative images need HTTPS and descriptive text';end if;
  if new.status in ('approved','active') and s.status<>'approved' then raise exception 'Approve the sponsor before the campaign';end if;
 elsif tg_table_name='revenue_records' then
  if tg_op='UPDATE' then raise exception 'Revenue records are immutable; append a documented adjustment';end if;
  if e34_private.commercial_url_host(new.evidence_url) is null then raise exception 'Revenue requires evidence from an authorized report or record';end if;
  if new.kind='reversal' then
   select * into original from e34_private.revenue_records where id=new.reverses_id for update;
   if original.id is null or original.kind<>'earning' or original.currency<>new.currency or original.channel<>new.channel then raise exception 'Reverse an existing earning in the same currency and channel';end if;
   if new.amount_cents+(select coalesce(sum(amount_cents),0) from e34_private.revenue_records where reverses_id=original.id)>original.amount_cents then raise exception 'Reversal exceeds the remaining earning';end if;
  end if;
 elsif tg_table_name in ('affiliate_commissions','sponsorship_payments') then
  if e34_private.commercial_url_host(new.evidence_url) is null then raise exception 'A dated source record is required';end if;
 end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION e34_private.guard_community()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); parent public.threads; target public.posts; recent integer; is_staff boolean;
begin
 -- FK cleanup may affect a discussion by another author. Only permit the
 -- precise nulling operation after its referenced public snapshot is gone.
 if tg_table_name='threads' and tg_op='UPDATE' then
  if old.journal_update_id is not null and new.journal_update_id is null
   and (to_jsonb(new)-'journal_update_id')=(to_jsonb(old)-'journal_update_id')
   and not exists(select 1 from public.garage_journal_entries where id=old.journal_update_id) then return new; end if;
  if to_jsonb(old)->>'garage_entry_id' is not null and to_jsonb(new)->>'garage_entry_id' is null
   and (to_jsonb(new)-'garage_entry_id')=(to_jsonb(old)-'garage_entry_id')
   and not exists(select 1 from public.garage_showcases where id=(to_jsonb(old)->>'garage_entry_id')::uuid) then return new; end if;
 end if;
 if tg_table_name='threads' then
  new.category:=case new.category when 'Technical help' then 'Technical Help & Troubleshooting' when 'Parts & fitment' then 'Parts, Compatibility & Sourcing' when 'Build journals' then 'Restorations & Build Journals' when 'General discussion' then 'General E34 Community' else new.category end;
  if cardinality(new.tag_ids)<>(select count(distinct x) from unnest(new.tag_ids) x) or exists(select 1 from unnest(new.tag_ids) x where not exists(select 1 from public.community_tags t where t.id=x and t.member_assignable)) then raise exception 'Choose up to twelve distinct community tags'; end if;
 end if;
 if actor is null then return new; end if;
 is_staff:=e34_private.has_role('moderator') and coalesce(auth.jwt()->>'aal','')='aal2';
 if tg_op='UPDATE' and (new.hidden is distinct from old.hidden or (tg_table_name='threads' and (to_jsonb(new)->>'locked') is distinct from (to_jsonb(old)->>'locked'))) and not is_staff then raise exception 'Moderator permission and MFA required'; end if;
 if new.author_id<>actor then
  if not is_staff then raise exception 'Moderator permission and MFA required'; end if;
  return new;
 end if;
 perform e34_private.community_can_contribute(actor);
 if tg_op='INSERT' then
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text,0));
  if exists(select 1 from auth.users where id=actor and created_at>now()-interval '24 hours') then
   if (select count(*) from regexp_matches(new.body,'https?://','g'))>2 then raise exception 'New members can include up to two external links per post'; end if;
   if tg_table_name='threads' then select count(*) into recent from public.threads where author_id=actor and created_at>now()-interval '1 hour';
   else select count(*) into recent from public.posts where author_id=actor and created_at>now()-interval '1 hour'; end if;
   if recent >= (case when tg_table_name='threads' then 3 else 10 end) then raise exception 'New-member posting limit reached. Please try again later.'; end if;
  end if;
 end if;
 if tg_table_name='threads' then
  if tg_op='INSERT' and new.locked then raise exception 'New discussions cannot be locked by their author'; end if;
 end if;
 if tg_table_name='posts' then
  if tg_op='UPDATE' and new.in_reply_to_post_id is distinct from old.in_reply_to_post_id then raise exception 'Reply context is immutable'; end if;
  select * into parent from public.threads where id=new.thread_id;
  if tg_op='INSERT' and (parent.id is null or parent.hidden or parent.locked) then raise exception 'This discussion is closed to new replies'; end if;
  if tg_op='INSERT' and e34_private.community_blocked(actor,parent.author_id) then raise exception 'A member block prevents this reply'; end if;
  if new.in_reply_to_post_id is not null then
   select * into target from public.posts where id=new.in_reply_to_post_id and thread_id=new.thread_id;
   if tg_op='INSERT' and (target.id is null or target.hidden or e34_private.community_blocked(actor,target.author_id)) then raise exception 'This reply target is unavailable'; end if;
  end if;
  if tg_op='UPDATE' and char_length(btrim(new.body))<40 and exists(select 1 from public.community_feedback where explanation_post_id=new.id) then raise exception 'A bad-advice explanation must retain at least forty characters'; end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION e34_private.guard_contribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid := auth.uid(); recent integer;
begin
 if actor is null then return new; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor::text,0));
 if tg_op='INSERT' then
  if tg_table_name='threads' then select count(*) into recent from public.threads where author_id=actor and created_at>now()-interval '1 hour';
  elsif tg_table_name='posts' then select count(*) into recent from public.posts where author_id=actor and created_at>now()-interval '1 hour';
  elsif tg_table_name='reports' then select count(*) into recent from public.reports where reporter_id=actor and created_at>now()-interval '1 hour';
  else select count(*) into recent from public.review_submissions where author_id=actor and created_at>now()-interval '1 hour'; end if;
  if recent >= (case when tg_table_name='posts' then 40 else 10 end) then raise exception 'Contribution limit reached. Please try again later.'; end if;
  new.created_at:=now();
  if tg_table_name in ('threads','posts') then new.hidden:=false; end if;
 else
  if new.author_id<>old.author_id or new.created_at<>old.created_at then raise exception 'Ownership and creation time are immutable'; end if;
  if new.hidden is distinct from old.hidden and not e34_private.has_role('moderator') then raise exception 'Moderator permission required'; end if;
  if tg_table_name='posts' then
   if new.thread_id<>old.thread_id then raise exception 'Replies cannot move between discussions'; end if;
  end if;
  if tg_table_name='threads' then new.updated_at:=now(); end if;
 end if;
 return new;
end $function$

