CREATE OR REPLACE FUNCTION e34_private.set_community_feedback(target_post uuid, expected_version integer, feedback_value text, explanation text DEFAULT ''::text, reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_actor uuid:=auth.uid(); target public.posts; parent public.threads; reply_id uuid; existing public.community_feedback;
begin
 perform e34_private.community_can_contribute(v_actor);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_actor::text,0));
 if (select count(*) from e34_private.community_actions where community_actions.actor=v_actor and created_at>now()-interval '1 hour' and action='feedback')>=60 then raise exception 'Feedback limit reached. Please try again later.'; end if;
 select * into target from public.posts where id=target_post for update;
 select * into parent from public.threads where id=target.thread_id for key share;
 if target.id is null or target.hidden or parent.hidden or parent.id is null then raise exception 'This advice is unavailable'; end if;
 if target.author_id=v_actor then raise exception 'You cannot rate your own advice'; end if;
 if e34_private.community_blocked(v_actor,target.author_id) or e34_private.community_blocked(v_actor,parent.author_id) then raise exception 'A member block prevents this feedback'; end if;
 if target.content_version<>expected_version then raise exception 'This advice has changed. Read the latest version before rating it.'; end if;
 if feedback_value is null or feedback_value not in ('helpful','bad-advice','remove') then raise exception 'Choose Helpful or Bad advice'; end if;
 select * into existing from public.community_feedback where post_id=target_post and user_id=v_actor;
 if feedback_value='remove' then delete from public.community_feedback where post_id=target_post and user_id=v_actor;
 else
  if feedback_value='bad-advice' then
   if reason is null or reason not in ('configuration','incorrect','unsafe','unsupported','outdated','other') or char_length(btrim(explanation)) not between 40 and 6000 then raise exception 'Explain the concern in 40–6000 characters and choose a reason'; end if;
   if parent.locked then raise exception 'This discussion is closed. Report the concern to moderation.'; end if;
   if existing.value='bad-advice' and existing.target_version=expected_version and exists(select 1 from public.posts where id=existing.explanation_post_id and not hidden) then raise exception 'You already explained this vote. Edit your linked reply or remove the vote first.'; end if;
   insert into public.posts(thread_id,author_id,body,in_reply_to_post_id) values(target.thread_id,v_actor,explanation,target_post) returning id into reply_id;
  else reason:=null;
  end if;
  insert into public.community_feedback(post_id,user_id,value,target_version,reason_code,explanation_post_id)
   values(target_post,v_actor,feedback_value,expected_version,reason,reply_id)
   on conflict(post_id,user_id) do update set value=excluded.value,target_version=excluded.target_version,reason_code=excluded.reason_code,explanation_post_id=excluded.explanation_post_id,updated_at=now();
 end if;
 insert into e34_private.community_actions(actor,action) values(v_actor,'feedback');
 return reply_id;
end $function$

CREATE OR REPLACE FUNCTION e34_private.submit_guest_contribution(payload jsonb, target_thread uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=auth.uid(); row_data public.threads; created_id uuid; recent integer; previous_flag text;
begin
 if actor is null or not exists(select 1 from auth.users where id=actor and is_anonymous is true) then raise exception 'Start a guest session before submitting'; end if;
 if not exists(select 1 from auth.sessions where user_id=actor and id::text=auth.jwt()->>'session_id') then raise exception 'A current guest session is required'; end if;
 if payload is null or jsonb_typeof(payload)<>'object' or char_length(payload::text)>40000 then raise exception 'Invalid guest submission'; end if;
 if char_length(btrim(coalesce(payload->>'body',''))) not between 40 and 20000 then raise exception 'Write 40–20000 characters with the details of your question or reply'; end if;
 perform pg_advisory_xact_lock(hashtextextended(actor::text,0));
 select count(*) into recent from e34_private.guest_submissions where author_id=actor and created_at>now()-interval '24 hours' and ((target_thread is null and thread_id is not null) or (target_thread is not null and post_id is not null));
 if recent >= (case when target_thread is null then 2 else 10 end) then raise exception 'Guest posting limit reached. Please try again tomorrow or use a verified account'; end if;
 previous_flag:=current_setting('e34.guest_submission',true);
 perform set_config('e34.guest_submission',actor::text,true);
 perform e34_private.community_can_contribute(actor);
 insert into public.profiles(id,display_name) values(actor,'Guest '||left(replace(actor::text,'-',''),8)) on conflict(id) do nothing;
 if target_thread is not null then
   insert into public.posts(thread_id,author_id,body,hidden) values(target_thread,actor,payload->>'body',true) returning id into created_id;
 else
   if char_length(btrim(coalesce(payload->>'title',''))) not between 8 and 160 then raise exception 'Use a title of 8–160 characters'; end if;
   row_data:=jsonb_populate_record(null::public.threads,payload);
   insert into public.threads(author_id,title,body,category,template_id,starter_topic_id,tag_ids,model_id,engine,component_id,part_id,catalog_position_id,manual_chapter_id,guide_id,guide_revision,guide_step,journal_update_id,article_slug,diagnostic_slug,configuration_revision_id,node_id,garage_entry_id,vehicle_configuration,observations,hidden)
   values(actor,row_data.title,row_data.body,coalesce(row_data.category,'General E34 Community'),coalesce(row_data.template_id,'general'),row_data.starter_topic_id,coalesce(row_data.tag_ids,'{}'),row_data.model_id,row_data.engine,row_data.component_id,row_data.part_id,row_data.catalog_position_id,row_data.manual_chapter_id,row_data.guide_id,row_data.guide_revision,row_data.guide_step,row_data.journal_update_id,row_data.article_slug,row_data.diagnostic_slug,row_data.configuration_revision_id,row_data.node_id,row_data.garage_entry_id,coalesce(row_data.vehicle_configuration,'{}'),coalesce(row_data.observations,'[]'),true)
   returning id into created_id;
 end if;
 perform set_config('e34.guest_submission',coalesce(previous_flag,''),true);
 return created_id;
end $function$

CREATE OR REPLACE FUNCTION e34_private.twin_session_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g jsonb;
begin
 select graph into g from public.digital_twin_configuration_revisions where id=new.configuration_revision_id and configuration_id=new.configuration_id;
 if new.state->'schemaVersion' is distinct from '1'::jsonb or new.state->>'graphId' is distinct from g->>'id' or new.state->>'graphRevision' is distinct from g->>'revision' or coalesce(new.state->>'mode','') not in ('explore','constrained') then raise exception 'Invalid typed workshop identity'; end if;
 return new;
end; $function$

CREATE OR REPLACE FUNCTION e34_private.validate_twin_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g jsonb; snap jsonb; elem jsonb; dep jsonb; conn jsonb; node jsonb; ids text[]; connection_ids text[]; field text; selected_mode text;
begin
 select graph into g from public.digital_twin_configuration_revisions where id=new.configuration_revision_id and configuration_id=new.configuration_id and publication_status='published';
 if g is null then raise exception 'Configuration revision is unavailable'; end if;
 if jsonb_typeof(new.state)<>'object' or new.state->>'schemaVersion'<>'1' or new.state->>'graphId'<>g->>'id' or new.state->>'graphRevision'<>g->>'revision' or new.state->>'mode' not in ('explore','constrained') then raise exception 'Invalid workshop identity or mode'; end if;
 if not(new.state ?& array['schemaVersion','graphId','graphRevision','mode','present','past','future']) or (select count(*) from jsonb_object_keys(new.state))<>7 then raise exception 'Incomplete workshop state'; end if;
 if jsonb_typeof(new.state->'past')<>'array' or jsonb_typeof(new.state->'future')<>'array' or jsonb_array_length(new.state->'past')>100 or jsonb_array_length(new.state->'future')>100 then raise exception 'Invalid workshop history'; end if;
 select array_agg(n->>'id') into ids from jsonb_array_elements(g->'nodes') n;
 select coalesce(array_agg(n->>'id'),'{}') into connection_ids from jsonb_array_elements(g->'connections') n;
 selected_mode=new.state->>'mode';
 for snap in select new.state->'present' union all select value from jsonb_array_elements(new.state->'past') union all select value from jsonb_array_elements(new.state->'future') loop
  if jsonb_typeof(snap)<>'object' or not(snap ?& array['removed','hidden','detached','selected','explosion']) or (select count(*) from jsonb_object_keys(snap))<>5 then raise exception 'Invalid workshop snapshot'; end if;
  if jsonb_typeof(snap->'explosion')<>'number' or (snap->>'explosion')::numeric not between 0 and 1 then raise exception 'Invalid separation'; end if;
  if snap->'selected'<>'null'::jsonb and (jsonb_typeof(snap->'selected')<>'string' or not(snap->>'selected'=any(ids))) then raise exception 'Unknown selected node'; end if;
  foreach field in array array['removed','hidden','detached'] loop
   if jsonb_typeof(snap->field)<>'array' or jsonb_array_length(snap->field)>10000 then raise exception 'Invalid component list'; end if;
   if (select count(*) from jsonb_array_elements(snap->field))<>(select count(distinct value) from jsonb_array_elements(snap->field)) then raise exception 'Duplicate component identity'; end if;
   for elem in select value from jsonb_array_elements(snap->field) loop
    if jsonb_typeof(elem)<>'string' or not((elem#>>'{}')=any(case when field='detached' then connection_ids else ids end)) then raise exception 'Unknown component or connection'; end if;
   end loop;
  end loop;
  if snap->'removed' ? (g->'configuration'->>'rootNodeId') then raise exception 'Vehicle root cannot be removed'; end if;
  if selected_mode='constrained' then
   for node in select value from jsonb_array_elements(g->'nodes') loop
    if snap->'removed' ? (node->>'id') then
     if coalesce(node->'accuracy'->>'removal','missing') not in ('source-checked','verified') then raise exception 'Removal needs technical review'; end if;
     for dep in select value from jsonb_array_elements(g->'dependencies') where value->>'target'=node->>'id' loop
      if not(snap->'removed' ? (dep->>'prerequisite')) or dep->>'reviewState' not in ('source-checked','verified') or jsonb_array_length(dep->'evidence')=0 then raise exception 'Removal prerequisite is not satisfied'; end if;
     end loop;
     for conn in select value from jsonb_array_elements(g->'connections') where value->>'kind' in ('electrical','fluid') and (value->>'from'=node->>'id' or value->>'to'=node->>'id') loop
      if not(snap->'detached' ? (conn->>'id')) then raise exception 'Disconnect the documented connection first'; end if;
     end loop;
    end if;
   end loop;
  end if;
 end loop;
 new.updated_at=now(); return new;
end; $function$

CREATE OR REPLACE FUNCTION public.propose_comment_for_review(source_post uuid, expected_version integer, target_kind text, target_identity text, proposal text, source_url text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p public.posts; submission uuid;
begin
 select * into p from public.posts where id=source_post and not hidden;
 if p.id is null or not exists(select 1 from public.threads where id=p.thread_id and not hidden) then raise exception 'Comment unavailable'; end if;
 if p.content_version<>expected_version then raise exception 'Comment changed. Review its latest version first.'; end if;
 if target_kind='guide' then
  if not exists(select 1 from public.guides where id=target_identity) then raise exception 'Choose a canonical guide'; end if;
 elsif target_kind='part' then
  if not exists(select 1 from public.parts where id=target_identity) then raise exception 'Choose a canonical part'; end if;
 elsif target_kind='article' then
  if not exists(select 1 from public.reference_article_index where id=target_identity) then raise exception 'Choose a canonical article'; end if;
 else raise exception 'Choose a guide, part or article review target'; end if;
 insert into public.review_submissions(target_type,target_id,correction,evidence_url,source_post_id,source_post_version)
 values(target_kind,target_identity,proposal,source_url,source_post,expected_version) returning id into submission;
 return submission;
end $function$

